update merit_badges set
  description    = 'In Animation merit badge you’ll learn how to create animations, the ways in which animation is used and the fun and exciting career opportunities in animation.',
  requirements   = '[{"number":"1","text":"General Knowledge. Do the following:"},{"number":"2","text":"Principles of Animation. Choose five of the following 12 principles of animation, and discuss how each one makes an animation appear more believable: squash and stretch, anticipation, staging, straight ahead action and pose to pose, follow through and overlapping action, slow in and slow out, arcs, secondary action, timing, exaggeration, solid drawing, and appeal."},{"number":"3","text":"Projects. With your counselor''s approval, choose two animation techniques and do the following for each:"},{"number":"4","text":"Animation in our World. Do the following:"},{"number":"5","text":"Careers. Learn about three career opportunities in animation. Pick one and find out about the education, training, and experience required for this profession. Discuss your findings with your counselor. Explain why this profession might interest you."}]'::jsonb,
  bsa_url        = 'https://www.scouting.org/merit-badges/animation/',
  worksheet_url  = 'http://usscouts.org/mb/worksheets/Animation.pdf',
  difficulty     = 2
where name = 'Animation';

update merit_badges set
  description    = 'Architecture is not just the special buildings like cathedrals, museums, or sports stadiums we read about or see on television; it is as normal as the homes, places of worship, schools, and shopping malls where we live, worship, work, learn, and play every day. However, architecture is more than just common shelter; building has always satisfied the human need to create something of meaning. Even the simplest form of architecture is a work of art that requires thought and planning.',
  requirements   = '[{"number":"1","text":"Do the following:"},{"number":"2","text":"In following the Leave No Trace Seven Principles and the Outdoor Code, Scouts pledge to \"Travel and camp on durable surfaces\" and to \"Leave what you find\" and to \"Be conservation-minded.\" Discuss the following with your counselor:"},{"number":"3","text":"Do ONE of the following:"},{"number":"4","text":"Measure a room such as one where you live or where your troop meets. Make an accurately scaled drawing of the room''s floor plan showing walls, doors, closets, windows, and any built-in furniture or cabinets. Neatly label your drawing with the following: your name, the date, what room you drew, and the scale of the drawing. (Drawing scale: 1/4 inch = 1 foot)"},{"number":"5","text":"Find out about three career opportunities in architecture. Pick one and find out the education, training, and experience required for this profession. Discuss this with your counselor, and explain why this profession might interest you."}]'::jsonb,
  bsa_url        = 'https://www.scouting.org/merit-badges/architecture/',
  worksheet_url  = 'http://usscouts.org/mb/worksheets/Architecture.pdf',
  difficulty     = 2
where name = 'Architecture and Construction';

update merit_badges set
  description    = 'This merit badge concentrates on two-dimensional art, specifically drawing and painting in various media, including an introduction to design applications in the fields of graphic arts and industrial design, history and design principles, and how these fields relate to fine art.',
  requirements   = '[{"number":"1","text":"Discuss the following with your counselor:"},{"number":"2","text":"Discuss with your counselor the following terms and elements of art: line, value, shape, form, space, color, and texture. Show examples of each element."},{"number":"3","text":"Discuss with your counselor the six principles of design: rhythm, balance, proportion, variety, emphasis, and unity."},{"number":"4","text":"Render a subject of your choice in FOUR of these ways:"},{"number":"5","text":"Do ONE of the following:"},{"number":"6","text":"With your parent or guardian''s permission and your counselor''s approval, visit a museum, art exhibit, art gallery, artists'' co-op, or artist''s workshop. Find out about the art displayed or created there. Discuss what you learned with your counselor."},{"number":"7","text":"Find out about three career opportunities in art. Pick one and find out the education, training, and experience required for this profession. Discuss this with your counselor, and explain why this profession might interest you."}]'::jsonb,
  bsa_url        = 'https://www.scouting.org/merit-badges/art/',
