update merit_badges set
  description    = 'Chess is among the oldest board games in the world, and it ranks among the most popular games ever created. Chess is played worldwide—even over the Internet. Players meet for fun and in competition, everywhere from kitchen tables and park benches to formal international tournaments.',
  requirements   = '[{"number":"1","text":"Do the following:"},{"number":"2","text":"Discuss with your counselor the following:"},{"number":"3","text":"Demonstrate to your counselor that you know each of the following. Then, using Scouting EDGE to teach someone who does not know how to play chess:"},{"number":"4","text":"Do the following:"},{"number":"5","text":"Do the following:"},{"number":"6","text":"Explain to your counselor how chess tournaments are run, including the Swiss system tournament format, the round robin tournament format, pairings for each round, time controls, touch move, scoring, and chess ratings."},{"number":"7","text":"Do ONE of the following:"}]'::jsonb,
  bsa_url        = 'https://www.scouting.org/merit-badges/chess/',
