update merit_badges set
  description    = 'Coin collecting is one of the oldest of all hobbies. Hoards of ancient coins found in excavations indicate that coins were one of the first collectibles. From earliest times, people valued coins not only as a means of trading and storing wealth, but also as miniature works of art.',
  requirements   = '[{"number":"1","text":"Understand how coins are made and where the active U.S. Mint facilities are located."},{"number":"2","text":"Explain the following terms: obverse, reverse, reeding, clad, type set, and date set."},{"number":"3","text":"Describe three different ways to store a collection, and the benefits, drawbacks, and cost of each method."},{"number":"4","text":"Do the following and explain to your counselor the design features, designer name, designer initials, and where to find them for each item:"},{"number":"5","text":"Describe and discuss with your counselor the special reverse designs of the quarters, half dollar and dollar coin struck in 1975-1976 to honor the U.S. Bicentennial."},{"number":"6","text":"Identify for your counselor the people depicted on current currency: $1, $2, $5, $10, $20, $50, and $100 notes. Explain where United States currency is printed."},{"number":"7","text":"Do ONE of the following:"}]'::jsonb,
  bsa_url        = 'https://www.scouting.org/merit-badges/coin-collecting/',
  worksheet_url  = 'http://usscouts.org/mb/worksheets/Coin-Collecting.pdf',
  difficulty     = 2
where name = 'Coin Collecting';

update merit_badges set
  description    = 'Discover how collecting can be an educational and financially rewarding pastime with the Collections Merit Badge. Scouts will prepare a brief written report, give a detailed description, and explain the development of their collection while demonstrating the knowledge of preserving and displaying their most prized possessions.',
  requirements   = '[{"number":"1","text":"Prepare a short written report or outline for your counselor, giving a detailed description of your collection, including a short history, why you enjoy your collection, and what you have learned from collecting. Be sure to include why you chose that particular type of collection/collecting method."},{"number":"2","text":"Explain the growth and development of your collection."},{"number":"3","text":"Demonstrate your knowledge of preserving and displaying your collection."},{"number":"4","text":"Demonstrate your knowledge of collecting and investing. Discuss with your counselor:"},{"number":"5","text":"Do the following:"},{"number":"6","text":"Discuss with your counselor the plans you have to continue with the collection in the future."},{"number":"7","text":"Find out about career opportunities in collecting. Pick one and find out the education, training, and experience required for this profession. Discuss this with your counselor, and explain why this profession might interest you."}]'::jsonb,
  bsa_url        = 'https://www.scouting.org/merit-badges/collections/',
  worksheet_url  = 'http://usscouts.org/mb/worksheets/Collections.pdf',
  difficulty     = 2
where name = 'Collections';

update merit_badges set
  description    = 'Games come in almost every shape, size, format, and flavor imaginable. Games can be fast-paced, slow, or anything in between. Some are competitive. Some are cooperative. They may be for individuals, small groups, or thousands of players at a time. They might take seconds to complete or last for years. However you slice it, everyone has played games, and games help make us who we are.',
  requirements   = '[{"number":"1","text":"Do the following:"},{"number":"2","text":"Discuss with your counselor FIVE of the following 17 game design terms. For each term that you pick, describe how it relates to a specific game: story, setting, characters, play sequence, level design, interface design, difficulty, balance, depth, pace, replay value, age appropriateness, single-player vs. multiplayer, cooperative vs. competitive, turn-based vs. real-time, strategy vs. reflex vs. chance, or abstract vs. thematic."},{"number":"3","text":"Define the term intellectual property. Describe the types of intellectual property associated with the game design industry. Describe how intellectual property is protected and why protection is necessary. Define and give an example of a licensed property."},{"number":"4","text":"Do the following:"},{"number":"5","text":"Design a new game. Any game medium or combination of mediums is acceptable. Record your work in a game design notebook."},{"number":"6","text":"Do the following: Note: You must have your counselor''s approval of your concept before you begin creating the prototype."},{"number":"7","text":"Blind test your game. Do the following:"},{"number":"8","text":"Do ONE of the following:"}]'::jsonb,
  bsa_url        = 'https://www.scouting.org/merit-badges/game-design/',
  worksheet_url  = 'http://usscouts.org/mb/worksheets/Game-Design.pdf',
  difficulty     = 3
where name = 'Game Design';

update merit_badges set
  description    = 'The field of graphic arts includes many kinds of work in the printing and publishing industries. Graphic arts professionals are involved in the creation of all kinds of printed communication, from business cards to books to billboards. The scope of printing communications is huge.',
  requirements   = '[{"number":"1","text":"Review with your counselor the processes for producing printed communications: offset lithography, screen printing, electronic/digital, relief, and gravure. Collect samples of three products, each one produced using a different printing process, or draw diagrams to help you with your description."},{"number":"2","text":"Explain the differences between continuous tone, line, and halftone artwork. Describe how digital images can be created and/or stored in a computer."},{"number":"3","text":"Design a printed piece (flyer, T-shirt, program, form, etc.). Explain your decisions for the typeface or typefaces you use and the way you arrange the elements in your design. Explain which printing process is best suited for printing your design. If desktop publishing is available, identify what hardware and software would be appropriate for outputting your design."},{"number":"4","text":"Produce the design you created for requirement 3 using one of the following printing processes:"},{"number":"5","text":"Postpress Operations. Do the following:"},{"number":"6","text":"Do ONE of the following, and then describe the highlights of your visit:"},{"number":"7","text":"Find out about three career opportunities in graphic arts. Pick one and find out the education, training, and experience required for this profession. Discuss this with your counselor, and explain why this profession might interest you."}]'::jsonb,
  bsa_url        = 'https://www.scouting.org/merit-badges/graphic-arts/',
  worksheet_url  = 'http://usscouts.org/mb/worksheets/Graphic-Arts.pdf',
  difficulty     = 2
where name = 'Graphic Arts';

